  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: rgba(255, 255, 255, 0.94);
      --surface-strong: #ffffff;
      --text: #182033;
      --muted: #5d6881;
      --border: #cfd8e6;
      --accent: #4f6df5;
      --accent-strong: #3551d1;
      --danger: #c62828;
      --shadow: 0 24px 60px rgba(24, 32, 51, 0.12);
      --radius: 24px;
      --focus-ring: 0 0 0 4px rgba(79, 109, 245, 0.22);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(79, 109, 245, 0.18), transparent 32%),
        linear-gradient(180deg, #f7f9fd 0%, #eef3f9 100%);
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface-strong);
      transform: translateY(-140%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      box-shadow: var(--focus-ring);
      outline: none;
    }

    main {
      display: grid;
      place-items: center;
      padding: 2rem 1rem 3rem;
    }

    .page-shell {
      width: min(100%, 68rem);
    }

    .hero-card {
      display: grid;
      gap: 1.75rem;
      padding: clamp(1.5rem, 2vw + 1rem, 3rem);
      border: 1px solid rgba(207, 216, 230, 0.9);
      border-radius: var(--radius);
      background: var(--surface);
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
    }

    .hero-copy {
      max-width: 32rem;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent-strong);
      font-size: 0.88rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 3.2rem);
      line-height: 1.05;
    }

    .intro {
      margin: 1rem 0 0;
      color: var(--muted);
      font-size: 1.02rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    .form-field.full-width {
      grid-column: 1 / -1;
    }

    label {
      font-weight: 600;
      line-height: 1.4;
    }

    .required-indicator {
      color: var(--accent-strong);
    }

    input {
      width: 100%;
      padding: 0.95rem 1rem;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface-strong);
      color: var(--text);
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #8b93a7;
    }

    input:hover {
      border-color: #aab6ca;
    }

    input:focus-visible,
    button:focus-visible {
      outline: none;
      box-shadow: var(--focus-ring);
    }

    input:focus-visible {
      border-color: var(--accent);
      transform: translateY(-1px);
    }

    .field-help,
    .field-error,
    .form-note {
      margin: 0;
      font-size: 0.92rem;
      line-height: 1.5;
    }

    .field-help,
    .form-note {
      color: var(--muted);
    }

    .field-error {
      color: var(--danger);
      font-weight: 600;
    }

    .has-error input {
      border-color: var(--danger);
      box-shadow: 0 0 0 1px var(--danger);
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1rem;
      margin-top: 0.25rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #ffffff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
      box-shadow: 0 18px 34px rgba(53, 81, 209, 0.26);
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 22px 38px rgba(53, 81, 209, 0.3);
    }

    button:active {
      transform: translateY(0);
    }

    .status-message {
      min-height: 1.5rem;
      font-weight: 600;
      color: var(--accent-strong);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 42rem) {
      .form-grid {
        grid-template-columns: 1fr;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
      }

      .hero-card,
      input,
      button,
      .skip-link {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
      }

      .field-error {
        color: Mark;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <main id="maincontent" tabindex="-1">
    <div class="page-shell">
      <section class="hero-card" aria-labelledby="support-heading">
        <div class="hero-copy">
          <p class="eyebrow">Support</p>
          <h1 id="support-heading">Talk to our support team</h1>
          <p class="intro">Share your details and we will follow up with the right specialist as soon as possible.</p>
        </div>

        <form id="support-form" novalidate>
          <p class="form-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>

          <div class="form-grid">
            <div class="form-field">
              <label for="full-name">
                Full name <span class="required-indicator" aria-hidden="true">*</span><span class="sr-only"> required</span>
              </label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-describedby="full-name-error"
                placeholder="Jordan Lee"
              >
              <p id="full-name-error" class="field-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="email-address">
                Email address <span class="required-indicator" aria-hidden="true">*</span><span class="sr-only"> required</span>
              </label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                required
                aria-describedby="email-address-error"
                placeholder="name@example.com"
              >
              <p id="email-address-error" class="field-error" hidden></p>
            </div>

            <div class="form-field full-width">
              <label for="phone-number">Phone number <span class="field-help">(optional)</span></label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                inputmode="tel"
                aria-describedby="phone-help phone-number-error"
                placeholder="(555) 123-4567"
              >
              <p id="phone-help" class="field-help">Optional. Use digits, spaces, or punctuation, for example (555) 123-4567.</p>
              <p id="phone-number-error" class="field-error" hidden></p>
            </div>
          </div>

          <div class="actions">
            <button type="submit">Send request</button>
            <p id="form-status" class="status-message" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");
    const fields = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Error: Enter your full name.";
          }

          if (value.trim().length < 2) {
            return "Error: Enter a full name with at least 2 characters.";
          }

          return "";
        }
      },
      {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Error: Enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!emailPattern.test(value.trim())) {
            return "Error: Enter a valid email address, like name@example.com.";
          }

          return "";
        }
      },
      {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          if (!value.trim()) {
            return "";
          }

          const phonePattern = /^\+?[\d\s().-]{7,20}$/;

          if (!phonePattern.test(value.trim())) {
            return "Error: Enter a phone number using digits, spaces, or punctuation, like (555) 123-4567.";
          }

          return "";
        }
      }
    ];

    const touchedFields = new WeakSet();

    function showError(fieldConfig, message) {
      const { input, error } = fieldConfig;
      const wrapper = input.closest(".form-field");

      if (!message) {
        error.textContent = "";
        error.hidden = true;
        input.removeAttribute("aria-invalid");
        wrapper.classList.remove("has-error");
        return true;
      }

      error.textContent = message;
      error.hidden = false;
      input.setAttribute("aria-invalid", "true");
      wrapper.classList.add("has-error");
      return false;
    }

    function validateField(fieldConfig, shouldShowError) {
      const message = fieldConfig.validate(fieldConfig.input.value);

      if (shouldShowError) {
        return showError(fieldConfig, message);
      }

      if (!message) {
        showError(fieldConfig, "");
      }

      return !message;
    }

    fields.forEach((fieldConfig) => {
      fieldConfig.input.addEventListener("blur", () => {
        touchedFields.add(fieldConfig.input);
        validateField(fieldConfig, true);
      });

      fieldConfig.input.addEventListener("input", () => {
        if (touchedFields.has(fieldConfig.input)) {
          validateField(fieldConfig, true);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusMessage.textContent = "";

      let firstInvalidField = null;

      fields.forEach((fieldConfig) => {
        touchedFields.add(fieldConfig.input);
        const isValid = validateField(fieldConfig, true);

        if (!isValid && !firstInvalidField) {
          firstInvalidField = fieldConfig.input;
        }
      });

      if (firstInvalidField) {
        statusMessage.textContent = "Please correct the highlighted fields and try again.";
        firstInvalidField.focus();
        return;
      }

      statusMessage.textContent = "Thanks. Your support request is ready to be reviewed.";
      form.reset();
      fields.forEach((fieldConfig) => {
        showError(fieldConfig, "");
      });
    });
  </script>
</body>
</html>
