  <title>Support contact form</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: rgba(255, 255, 255, 0.94);
      --surface-strong: #ffffff;
      --text: #182033;
      --muted: #5d6881;
