      border-radius: 999px;
      background: var(--surface-strong);
      transform: translateY(-140%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      box-shadow: var(--focus-ring);
      outline: 3px solid var(--focus-outline);
      outline-offset: 3px;
    }

    main {
      display: grid;
      place-items: center;
      padding: 2rem 1rem 3rem;
    }

    .page-shell {
      width: min(100%, 68rem);
    }

    .hero-card {
      display: grid;
      gap: 1.75rem;
      padding: clamp(1.5rem, 2vw + 1rem, 3rem);
      border: 1px solid rgba(207, 216, 230, 0.9);
      border-radius: var(--radius);
      background: var(--surface);
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
    }

    .hero-copy {
      max-width: 32rem;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent-strong);
      font-size: 0.88rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 3.2rem);
      line-height: 1.05;
    }

    .intro {
      margin: 1rem 0 0;
      color: var(--muted);
      font-size: 1.02rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    .form-field.full-width {
      grid-column: 1 / -1;
    }

    label {
      font-weight: 600;
      line-height: 1.4;
    }

    .required-indicator {
      color: var(--accent-strong);
    }

    input {
      width: 100%;
      padding: 0.95rem 1rem;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface-strong);
      color: var(--text);
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #8b93a7;
    }

    input:hover {
      border-color: #aab6ca;
    }

    input:focus-visible,
    button:focus-visible {
      outline: 3px solid var(--focus-outline);
      outline-offset: 3px;
