      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #ffffff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
      box-shadow: 0 18px 34px rgba(53, 81, 209, 0.26);
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 22px 38px rgba(53, 81, 209, 0.3);
    }

    button:active {
      transform: translateY(0);
    }

    .status-message {
      min-height: 1.5rem;
      font-weight: 600;
      color: var(--accent-strong);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
