<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <main id="maincontent" tabindex="-1">
    <div class="page-shell">
      <section class="hero-card" aria-labelledby="support-heading">
        <div class="hero-copy">
          <p class="eyebrow">Support</p>
          <h1 id="support-heading">Talk to our support team</h1>
          <p class="intro">Share your details and we will follow up with the right specialist as soon as possible.</p>
        </div>

        <form id="support-form" novalidate>
          <p class="form-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>

          <div class="form-grid">
            <div class="form-field">
              <label for="full-name">
                Full name <span class="required-indicator" aria-hidden="true">*</span><span class="sr-only"> required</span>
              </label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-errormessage="full-name-error"
                placeholder="Jordan Lee"
              >
              <p id="full-name-error" class="field-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="email-address">
                Email address <span class="required-indicator" aria-hidden="true">*</span><span class="sr-only"> required</span>
              </label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                required
                aria-errormessage="email-address-error"
                placeholder="name@example.com"
              >
              <p id="email-address-error" class="field-error" hidden></p>
            </div>

            <div class="form-field full-width">
              <label for="phone-number">Phone number <span class="field-help">(optional)</span></label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                inputmode="tel"
                aria-describedby="phone-help"
                aria-errormessage="phone-number-error"
                placeholder="(555) 123-4567"
              >
              <p id="phone-help" class="field-help">Optional. Use digits, spaces, or punctuation, for example (555) 123-4567.</p>
              <p id="phone-number-error" class="field-error" hidden></p>
            </div>
          </div>

          <div class="actions">
            <button type="submit">Send request</button>
            <p id="form-status" class="status-message" role="status" aria-live="polite" aria-atomic="true"></p>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");
    const fields = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        baseDescribedBy: "",
        validate(value) {
          if (!value.trim()) {
            return "Error: Enter your full name.";
          }

          if (value.trim().length < 2) {
            return "Error: Enter a full name with at least 2 characters.";
          }

          return "";
        }
      },
      {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        baseDescribedBy: "",
        validate(value) {
          if (!value.trim()) {
            return "Error: Enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!emailPattern.test(value.trim())) {
            return "Error: Enter a valid email address, like name@example.com.";
          }

          return "";
        }
      },
      {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        baseDescribedBy: "phone-help",
        validate(value) {
          if (!value.trim()) {
            return "";
          }

          const phonePattern = /^\+?[\d\s().-]{7,20}$/;

          if (!phonePattern.test(value.trim())) {
            return "Error: Enter a phone number using digits, spaces, or punctuation, like (555) 123-4567.";
          }

          return "";
        }
      }
    ];

    const touchedFields = new WeakSet();

    function showError(fieldConfig, message) {
      const { input, error } = fieldConfig;
      const wrapper = input.closest(".form-field");
      const descriptions = fieldConfig.baseDescribedBy ? [fieldConfig.baseDescribedBy] : [];

      if (!message) {
        error.textContent = "";
        error.hidden = true;
        input.removeAttribute("aria-invalid");
        if (descriptions.length > 0) {
          input.setAttribute("aria-describedby", descriptions.join(" "));
        } else {
          input.removeAttribute("aria-describedby");
        }
        wrapper.classList.remove("has-error");
        return true;
      }

      error.textContent = message;
      error.hidden = false;
      input.setAttribute("aria-invalid", "true");
      descriptions.push(error.id);
      input.setAttribute("aria-describedby", descriptions.join(" "));
      wrapper.classList.add("has-error");
      return false;
    }

    function validateField(fieldConfig, shouldShowError) {
      const message = fieldConfig.validate(fieldConfig.input.value);

      if (shouldShowError) {
        return showError(fieldConfig, message);
      }

      if (!message) {
        showError(fieldConfig, "");
      }

      return !message;
    }

    fields.forEach((fieldConfig) => {
      fieldConfig.input.addEventListener("blur", () => {
        touchedFields.add(fieldConfig.input);
        validateField(fieldConfig, true);
      });

      fieldConfig.input.addEventListener("input", () => {
        if (touchedFields.has(fieldConfig.input)) {
          validateField(fieldConfig, true);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusMessage.textContent = "";

      let firstInvalidField = null;

      fields.forEach((fieldConfig) => {
        touchedFields.add(fieldConfig.input);
        const isValid = validateField(fieldConfig, true);

        if (!isValid && !firstInvalidField) {
          firstInvalidField = fieldConfig.input;
        }
      });

      if (firstInvalidField) {
        statusMessage.textContent = "Please correct the highlighted fields and try again.";
        firstInvalidField.focus();
        return;
      }

      statusMessage.textContent = "Thanks. Your support request is ready to be reviewed.";
      form.reset();
      fields.forEach((fieldConfig) => {
        showError(fieldConfig, "");
      });
    });
  </script>
</body>
</html>
